import { useDispatch } from 'react-redux';

function AddProject() {
  const dispatch = useDispatch();

  const handleAdd = () => {
    dispatch(addProject('My First Project'));
  };

  return <button onClick={handleAdd}>Add Project</button>;
}

export default AddProject;
